'use strict';
// Ein eigener Bereich für persönliche Nachweise der Ausbildungsleitung.
const kfStaffProofNavBase=buildNav;
buildNav=function(){kfStaffProofNavBase();if(user&&['admin','chief'].includes(user.role))$('#nav').insertAdjacentHTML('beforeend',`<button data-nav="staffproofs" class="${route==='staffproofs'?'active':''}">${icon('reports')}<span>Meine Scheine & Weiterbildung</span></button>`);};
const kfStaffProofRenderBase=render;
render=function(){if(route!=='staffproofs'||!user||!['admin','chief'].includes(user.role))return kfStaffProofRenderBase();buildNav();const list=state.staffProofs;if(!Array.isArray(list)){$('#content').innerHTML=heading('MEINE NACHWEISE','Scheine & Weiterbildung','Bitte zuerst Apps Script auf Version 1.3.0 aktualisieren und die bestehende Bereitstellung aktualisieren.');return;}$('#content').innerHTML=heading('MEINE NACHWEISE','Scheine & Weiterbildung','Persönliche Führerscheine, Qualifikationen und Weiterbildungen mit Dokument hinterlegen.',state.preview?'':`<button class="button teal" type="button" data-staff-proof="new">+ Nachweis hinzufügen</button>`)+(list.length?`<div class="kf-proof-grid">${list.map(p=>`<article class="panel"><span class="eyebrow">${esc(p.category)}</span><h2>${esc(p.title)}</h2><p class="small muted">${p.issued?'Abgeschlossen / ausgestellt: '+date(p.issued)+'<br>':''}${p.expires?'Gültig bis: '+date(p.expires):'Kein Ablaufdatum eingetragen'}</p>${p.expires&&p.expires<today()?'<p class="kf-expiry overdue">Abgelaufen – Erneuerung prüfen</p>':''}${p.notes?`<p class="prose">${esc(p.notes)}</p>`:''}<div class="inline-actions"><button class="button secondary small" type="button" data-staff-proof="download" data-id="${esc(p.fileId)}">Dokument öffnen</button>${state.preview?'':`<button class="button secondary small" type="button" data-staff-proof="edit" data-id="${esc(p.id)}">Bearbeiten</button>`}</div></article>`).join('')}</div>`:empty('Noch keine eigenen Nachweise.','Führerscheine und Weiterbildungen kannst du hier für dein Konto hinterlegen.'));kfDecorate();};
function kfStaffProofEditor(id){const p=(state.staffProofs||[]).find(x=>x.id===id)||{};openModal(id?'Nachweis bearbeiten':'Nachweis hinzufügen',`<form id="kfOwnProofForm" data-id="${esc(id)}"><div class="form-grid">${select('Art *','category',['Führerschein','Feuerwehrführerschein','Kranschein','Bootsschein','Staplerschein','Weiterbildung','Sonstiger Nachweis'].map(x=>[x,x]),p.category||'Führerschein')}${field('Bezeichnung / Klasse *','title',p.title||'','text','required placeholder="z. B. Führerschein B und C oder Fortbildung"')}${field('Abgeschlossen / ausgestellt am','issued',p.issued||'','date')}${field('Gültig bis (falls befristet)','expires',p.expires||'','date')}<label>Dokument ${p.fileId?'ersetzen (optional)':'*'}<input name="file" type="file" accept="application/pdf,image/jpeg,image/png" ${p.fileId?'':'required'}><small>PDF, JPG oder PNG, höchstens 2 MB.</small></label><div class="full">${area('Bemerkung','notes',p.notes||'')}</div></div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button teal" type="submit">Nachweis speichern</button></div></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-staff-proof]');if(!b||busy)return;const action=b.dataset.staffProof,id=b.dataset.id||'';if(action==='download'){operation(async()=>downloadData(await api('download',{fileId:id})));return;}if(state.preview){toast('Die Vorschau ist schreibgeschützt.',true);return;}if(action==='new'||action==='edit')kfStaffProofEditor(id);});
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='kfOwnProofForm')return;e.preventDefault();if(busy||state.preview)return;operation(async()=>{const d=new FormData(f),file=d.get('file'),record={id:f.dataset.id,category:d.get('category'),title:d.get('title'),issued:d.get('issued'),expires:d.get('expires'),notes:d.get('notes')};if(file&&file.size){if(file.size>2*1024*1024)throw Error('Maximal 2 MB pro Dokument.');record.name=file.name;record.mime=file.type;record.base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Datei konnte nicht gelesen werden.'));reader.readAsDataURL(file);});}await api('saveStaffProof',record);closeModal();await load();toast('Nachweis gespeichert.');});});
